(()=>{const root=document.getElementById('rl-camera-review'),content=root.querySelector('#rl-camera-content'),overlay=root.querySelector('#rl-camera-overlay');const photos=['assets/landscape-1.jpg','assets/landscape-2.jpg','assets/landscape-3.jpg'].map(path=>path.startsWith('data:')?path:(root.dataset.assetBase||'')+path);const i=n=>`<i data-lucide="${n}" aria-hidden="true"></i>`;const b=(a,label,icon,cls='')=>`<button data-action="${a}" aria-label="${label}" class="${cls}">${icon?i(icon):label}</button>`;let state={screen:'home',target:'import',camera:'α7C II',selected:[],filter:'全部照片',connected:true,shutter:'1/250',aperture:'f/4.0',iso:'400',ev:'+0.3',large:false,short:false,captured:0};function icons(){if(globalThis.lucide)lucide.createIcons({attrs:{width:20,height:20}})}function persist(){if(root.closest('#rl-mobile-review'))return;if(window.openai?.setWidgetState)window.openai.setWidgetState({modelContent:{review:'RawLab camera',page:state.screen},privateContent:{screen:state.screen}}).catch(()=>{})}
function top(title,action='back',right='menu'){return `<div class="top">${b(action,'返回','chevron-left','icon')}<div class="title">${title}</div>${b(right,right==='menu'?'更多':'更换相机',right==='menu'?'ellipsis':'camera','icon')}</div>`}
function connectionPage(){
  return top(state.target==='import'?'连接相机以导入':'连接相机以拍摄')+`<div class="connect">
    <div class="connect-heading"><h3>选择相机</h3><button data-action="connection-guide">如何连接 ${i('chevron-right')}</button></div>
    <p class="instruction">打开相机的手机连接功能，然后选择附近的相机。</p>
    <button class="device" data-camera="α7C II">${i('camera')}<span>α7C II<small>已配对</small></span>${i('chevron-right')}</button>
    <button class="device" data-camera="ZV-E10">${i('camera')}<span>ZV-E10<small>相机 Wi-Fi</small></span>${i('chevron-right')}</button>
    <button class="device" data-camera="其他 Sony 相机">${i('camera')}<span>其他 Sony 相机<small>未验证机型示例 · 可尝试连接</small></span>${i('chevron-right')}</button>
    <div class="connect-actions"><button data-action="scan">${i('refresh-cw')}重新搜索</button>${b('manual-wifi','手动连接相机 Wi-Fi',null)}</div>
    <p class="compatibility-note">已验证机型仅供参考。其他机型也可尝试连接，可用功能以连接后的检测结果为准。</p>
  </div>`;
}
function connectionGuide(){
  return `<div class="top">${b('guide-back','返回选择相机','chevron-left','icon')}<div class="title">如何连接</div><span class="icon" aria-hidden="true"></span></div>
  <article class="connection-guide">
    <p class="guide-intro">相机菜单会随型号和固件变化。按机身提供的手机连接方式操作即可，无需先在已验证清单中找到型号。</p>
    <section><h3>连接前</h3><ul><li>打开相机并装入存储卡，让手机靠近相机。</li><li>打开手机 Wi-Fi；使用自动发现时开启蓝牙，并按系统提示允许所需的附近设备或定位权限。</li><li>如果相机正连接其他手机或遥控应用，先在那一端结束连接。</li></ul></section>
    <section><h3>相机支持蓝牙配对时</h3><ol><li>在相机的网络设置中，打开「智能手机连接」或对应的手机配对入口。</li><li>回到 RawLab 点「重新搜索」，选择相机。首次配对时，在手机与相机上确认提示。</li><li>同意系统加入相机 Wi-Fi 的请求，保持相机连接页面开启，等待 RawLab 检测可用功能。</li></ol><p class="guide-example">α7C II 示例：网络 → 连接/电脑遥控 → 智能手机连接，按机身提示开启蓝牙。<a href="https://helpguide.sony.net/ilc/2360/v1/en/contents/202h_register_smartphone.html" target="_blank" rel="noopener noreferrer">Sony 机身说明</a></p></section>
    <section><h3>相机显示 Wi-Fi 名称和密码时</h3><ol><li>在相机中打开智能手机控制或连接功能，找到相机显示的 Wi-Fi 名称（SSID）和密码。</li><li>打开手机系统 Wi-Fi，选择该名称并输入密码。提示「无互联网」时，选择保持连接。</li><li>返回 RawLab，点「手动连接相机 Wi-Fi」，再检测当前连接。</li></ol><p class="guide-example">初代 ZV-E10 示例：网络 → 智能手机连接 → 开启，再进入「连接」。显示二维码后，可按机身删除键切换到 SSID／密码。<a href="https://helpguide.sony.net/ilc/2070/v1/en/contents/TP1000201574.html" target="_blank" rel="noopener noreferrer">Sony 机身说明</a></p></section>
    <section><h3>用于联机拍摄时</h3><p>先把相机设为照片单拍，并确认相机端保留原件。若提供双端保存选项，可选择同时保存至相机与手机；传输大小选择原始大小。具体名称以机身显示为准。拍摄和参数调整能否使用，会在连接后分别显示。</p><p class="guide-example">α7C II：遥控拍摄设置 → 静止影像保存目的地 → Dest.+Camera。初代 ZV-E10 在「智能手机连接 → 遥控拍摄设置」中选择机身提供的保存目的地。<a href="https://helpguide.sony.net/ilc/2360/v1/en/contents/201h_remote_shoot_setting.html" target="_blank" rel="noopener noreferrer">α7C II 说明</a> · <a href="https://helpguide.sony.net/ilc/2070/v1/en/contents/TP1000201572.html" target="_blank" rel="noopener noreferrer">ZV-E10 说明</a></p></section>
    <section><h3>连接不上时</h3><dl><dt>搜索不到相机</dt><dd>确认相机的手机连接页面仍开启，手机蓝牙和所需权限可用，再重新搜索。</dd><dt>蓝牙已配对，但没有照片</dt><dd>蓝牙配对不等于 Wi-Fi 已连上。确认手机仍连接相机 Wi-Fi，然后回到 RawLab。</dd><dt>提示 Wi-Fi 没有互联网</dt><dd>这是相机直连网络的常见状态。保持这条连接，不要自动切回其他 Wi-Fi。</dd><dt>可以导入，但不能联机拍摄</dt><dd>导入、取景、快门和参数调整是不同能力。按当前连接显示的原因处理，必要时切换相机的手机连接模式。</dd></dl></section>
    <section><h3>未验证的机型也可以连接</h3><p>已验证清单只记录实际测试过的机型与固件，不作为连接门槛。未收录机型可以搜索、选择和尝试连接；若连接方式或某项功能不可用，会显示具体原因。</p></section>
    <button class="guide-return" data-action="guide-back">返回选择相机</button>
  </article>`;
}
function render(){let body='';if(state.screen==='home')body=top('相机')+`<div class="home"><div class="identity"><strong>${state.camera}</strong>上次使用的相机 · 未连接</div><button class="entry" data-entry="import">${i('images')}<span><strong>导入照片</strong><small>浏览存储卡，选择原件导入</small></span>${i('chevron-right')}</button><button class="entry" data-entry="tether">${i('camera')}<span><strong>联机拍摄</strong><small>实时取景、调整参数、拍后回传</small></span>${i('chevron-right')}</button><div style="margin-top:20px">${b('history','导入记录',null)}</div></div>`;
else if(state.screen==='connect')body=connectionPage();
else if(state.screen==='guide')body=connectionGuide();
else if(state.screen==='import')body=top(state.camera+' · 导入','back','menu')+`<div class="subbar"><span>${state.filter} · ${state.filter==='仅 RAW'?24:state.filter==='仅 JPEG'?12:36} 张</span><div>${b('filter','筛选','list-filter')}${b('selectall',state.selected.length?'取消选择':'全选',null)}</div></div><div class="grid">${Array.from({length:36},(_,n)=>n).filter(n=>state.filter==='全部照片'||(state.filter==='仅 JPEG'?n%3===0:n%3!==0)).map(n=>`<button class="tile ${state.selected.includes(n)?'selected':''}" data-photo="${n}" aria-label="选择 DSC0${4028+n}.${n%3===0?'JPG':'ARW'}" aria-pressed="${state.selected.includes(n)}"><img src="${photos[n%3]}" alt="相机示例照片 ${n+1}"><span class="check">${state.selected.includes(n)?i('check'):''}</span><span class="format">${n%3===0?'JPEG':'RAW'}</span><span class="name">DSC0${4028+n}</span></button>`).join('')}</div>${state.selected.length?`<div class="selection"><span>${state.selected.length} 张 · ${(state.selected.length*27.4).toFixed(0)} MB</span>${state.selected.length===1?b('preview','预览','maximize-2','icon'):''}${b('transfer','导入',null,'primary')}</div>`:''}`;
else{const disconnected=state.screen==='disconnected',readonly=state.screen==='readonly';body=top(state.camera+' · 联机','back','menu')+`<div class="viewfinder"><img src="${photos[0]}" alt="模拟实时取景"><span class="live-label">${disconnected?'已断开 · 最后画面':readonly?'P · 参数由机身控制':'M · 单张拍摄'}</span>${disconnected?'<div class="shade" style="inset:0;align-items:center;justify-content:center;background:#171719cc"><div class="empty">连接已断开<br>已保存的照片仍可查看<br>'+b('reconnect','重新连接',null,'primary')+'</div></div>':''}</div><div class="exposure">${[['shutter','快门'],['aperture','光圈'],['iso','ISO'],['ev','曝光补偿']].map(([k,t])=>`<button data-param="${k}" ${disconnected?'disabled':''} ${readonly?'data-readonly="true" aria-label="参数只读，查看原因"':''}><span>${state[k]}</span>${readonly?'<small>只读</small>':''}</button>`).join('')}</div><div class="controls">${b('recent','最近照片','image','icon')}<button class="shutter" data-action="capture" aria-label="拍摄" ${disconnected?'disabled':''}></button>${b('parameters','拍摄参数','sliders-horizontal','icon')}</div><div class="tether-state">${disconnected?'本次已保存 3 张':state.captured?'已保存 '+state.captured+' 张 · 原件已接收':'已连接 · 自动接收原件'}</div>`}
content.innerHTML=body;const phone=root.querySelector('.phone');phone.classList.toggle('large',state.large);phone.style.height=state.short?'670px':'';root.querySelector('#rl-camera-select').value=state.screen;icons();root.querySelector('#rl-camera-live').textContent=state.screen}
function sheet(title,body){overlay.innerHTML=`<div class="shade"><section class="sheet" role="dialog" aria-label="${title}"><div class="sheet-head"><span>${title}</span>${b('close','关闭','x','icon')}</div>${body}</section></div>`;icons()}
root.addEventListener('click',e=>{const x=e.target.closest('button');if(!x)return;if(x.dataset.entry){state.target=x.dataset.entry;state.screen='connect';render();return}if(x.dataset.camera){state.camera=x.dataset.camera;if(state.camera==='ZV-E10'&&state.target==='tether'){sheet('ZV-E10 拍摄设置','<p class="hint">请在相机中启用同时保存至相机与手机，再连接联机拍摄。</p>'+b('confirm-connect','设置完成，连接',null,'primary'))}else{state.screen=state.target;render()}return}if(x.dataset.photo){const n=Number(x.dataset.photo);state.selected=state.selected.includes(n)?state.selected.filter(a=>a!==n):[...state.selected,n];render();return}if(x.dataset.param){if(state.screen==='readonly'){sheet('当前参数只读','<div class="hint">此连接尚未确认支持参数写入。请在机身调整；应用只显示读取到的值。</div>'+b('close','知道了',null,'menuitem'));return}const key=x.dataset.param,values={shutter:['1/60','1/125','1/250','1/500'],aperture:['f/4.0','f/5.6','f/8.0'],iso:['100','200','400','800','1600'],ev:['−0.7','−0.3','0.0','+0.3','+0.7']};sheet({shutter:'快门速度',aperture:'光圈',iso:'ISO',ev:'曝光补偿'}[key],values[key].map(v=>`<button class="menuitem" data-setting="${key}" data-number="${v}">${v}${state[key]===v?' · 当前':''}</button>`).join('')+'<div class="hint">设计示例；实际选项由相机当前模式提供。</div>');return}if(x.dataset.setting){state[x.dataset.setting]=x.dataset.number;overlay.innerHTML='';render();return}
const a=x.dataset.action;if(a==='connection-guide'){state.screen='guide';overlay.innerHTML='';render();return}if(a==='guide-back'){state.screen='connect';render();return}if(a==='manual-wifi'){sheet('连接相机 Wi-Fi','<p class="hint">在手机系统 Wi-Fi 中加入相机显示的网络，然后返回检测。此处仅演示交互。</p>'+b('check-wifi','已连接，检测当前网络',null,'primary')+b('connection-guide','查看连接说明',null,'menuitem'));return}if(a==='check-wifi'){state.camera='其他 Sony 相机';state.screen=state.target;overlay.innerHTML='';render();return}if(a==='close'){overlay.innerHTML='';return}if(a==='back'&&state.screen==='home'&&root.closest('#rl-mobile-review')){root.dispatchEvent(new CustomEvent('review-open-editor',{bubbles:true}));return}if(a==='back'){if(state.screen==='home')sheet('返回编辑器','<p class="hint">从编辑器再次进入，仍先显示相机入口。</p>'+b('close','回到相机入口',null,'menuitem'));else{state.screen='home';render()}}
if(a==='menu')sheet('更多',b('change','更换相机',null,'menuitem')+b('location','保存位置',null,'menuitem')+b('history','导入记录',null,'menuitem')+(state.screen==='tether'?b('disconnect','断开连接',null,'menuitem'):'')+(state.screen==='tether'?'<label><input type="checkbox">构图网格</label><label><input type="checkbox">拍后审片</label>':''));if(a==='change'||a==='reconnect'){state.target=state.screen==='import'?'import':'tether';state.screen='connect';overlay.innerHTML='';render()}if(a==='confirm-connect'){state.screen='tether';overlay.innerHTML='';render()}if(a==='scan')sheet('搜索相机','<p class="hint">已找到 α7C II。若没有找到相机，可检查手机连接设置后重试。</p>'+b('close','返回设备列表',null,'menuitem'));
if(a==='selectall'){state.selected=state.selected.length?[]:Array.from({length:36},(_,n)=>n);render()}if(a==='filter')sheet('筛选照片','<label><input type="radio" name="rl-filter" value="全部照片" checked>全部照片</label><label><input type="radio" name="rl-filter" value="仅 RAW">仅 RAW</label><label><input type="radio" name="rl-filter" value="仅 JPEG">仅 JPEG</label><div class="hint">拍摄日期</div>'+b('dates','全部日期',null,'menuitem')+b('apply-filter','应用筛选',null,'primary'));
if(a==='apply-filter'){state.filter=overlay.querySelector('input[name="rl-filter"]:checked')?.value||'全部照片';overlay.innerHTML='';render()}if(a==='dates')sheet('拍摄日期',['全部日期','2026-11-10','2026-11-09'].map(t=>b('close',t,null,'menuitem')).join(''));
if(a==='transfer')sheet('导入完成',`<div class="progress"><span></span></div><p>${state.selected.length} 张原件已保存</p><p class="hint">此处为完成态示例，不读取相机或写入媒体库。</p>${b('edit','打开编辑',null,'primary')}${b('close','继续选片',null)}`);
if(a==='preview'||a==='recent')sheet(a==='preview'?'照片预览':'最近照片',`<img src="${photos[0]}" alt="示例原件预览" style="width:100%;max-height:360px;object-fit:contain"><div class="hint">DSC04028.ARW · 47.1 MB</div>${b('edit','打开编辑',null,'primary')}`);
if(a==='edit'&&root.closest('#rl-mobile-review')){overlay.innerHTML='';root.dispatchEvent(new CustomEvent('review-open-editor',{bubbles:true}));return}if(a==='edit')sheet('交接到编辑器','<p class="hint">以已保存的原件打开编辑器；有未确认调整时，先处理当前工具草稿。</p>'+b('close','返回',null,'menuitem'));
if(a==='parameters')sheet('拍摄参数',b('wb','白平衡 · 自动',null,'menuitem')+b('focus','对焦模式 · AF-C',null,'menuitem')+'<div class="hint">不可调整的参数显示机身提供的原因。</div>');if(a==='wb'||a==='focus')sheet(a==='wb'?'白平衡':'对焦模式',(a==='wb'?['自动','日光','阴天']:['AF-C','MF']).map(t=>b('close',t,null,'menuitem')).join(''));
if(a==='capture'){state.captured++;render()}if(a==='disconnect'){state.screen='disconnected';overlay.innerHTML='';render()}if(a==='history')sheet('导入记录','<div class="menuitem">今天 · α7C II · 3 张原件</div>');if(a==='location')sheet('保存位置','<div class="hint">系统媒体库 / RawLab / 拍摄日期<br>设置只影响之后的导入，不移动已保存照片。</div>')});
root.querySelector('#rl-camera-select').addEventListener('change',e=>{state.screen=e.target.value;overlay.innerHTML='';render();persist()});const restore=root.closest('#rl-mobile-review')?null:window.openai?.widgetState?.privateContent;if(['home','connect','guide','import','tether','readonly','disconnected'].includes(restore?.screen))state.screen=restore.screen;render();root.addEventListener('review-layout',e=>{state.large=!!e.detail.large;state.short=!!e.detail.short;render()});root.addEventListener('click',persist);root.addEventListener('review-navigate',e=>{state.screen=e.detail?.screen||'home';state.target=state.screen==='import'?'import':'tether';overlay.innerHTML='';render()});window.addEventListener('openai:set_globals',e=>{if(root.closest('#rl-mobile-review'))return;const p=e.detail?.globals?.widgetState?.privateContent;if(['home','connect','guide','import','tether','readonly','disconnected'].includes(p?.screen)){state.screen=p.screen;render()}});window.addEventListener('keydown',e=>{if(e.key==='Escape'&&!root.closest('[hidden]')){if(overlay.innerHTML){overlay.innerHTML='';return}if(state.screen==='guide'){state.screen='connect';render()}}});if(globalThis.Tweak){const tweak=new Tweak({container:root.querySelector('.phone'),onChange:render});tweak.addToggle(state,'large',{label:'大字模式'});tweak.addToggle(state,'short',{label:'短屏布局'})}
})();
